<?php
require __DIR__.'/support.php';
foreach (['mysql:host=localhost;dbname=issuer_a1_tests_prod','mysql:dbname=issuer_a1_tests;dbname=another','sqlite:dbname=issuer_a1_tests'] as $dsn) { a1reject(fn()=>a1validateDsn($dsn),'Only isolated issuer_a1_tests DB is allowed','unsafe test DSN rejected without connecting'); }
$a=a1fixture(); $b=a1fixture('22333444000155'); $none=a1fixture(null,30,'CN 11222333000181 must not count');
$m=IssuerCertificateParser::inspect($a['pfx'],$a['password'],'11.222.333/0001-81');
a1check($m['document']==='11222333000181'&&$m['document_status']==='matched','SAN otherName CNPJ match');
a1check(count($m)===8&&!str_contains(json_encode($m),'PRIVATE KEY')&&!str_contains(json_encode($m),$a['password']),'metadata is allowlisted');
a1check(IssuerCertificateParser::inspect($none['pfx'],$none['password'],'11222333000181')['document_status']==='unverified','missing OID remains unverified despite CN digits');
a1reject(fn()=>IssuerCertificateParser::inspect($b['pfx'],$b['password'],'11222333000181'),'issuer_certificate_document_mismatch','CNPJ mismatch');
a1reject(fn()=>IssuerCertificateParser::inspect($a['pfx'],'wrong','11222333000181'),'issuer_certificate_parse_failed','wrong password');
a1reject(fn()=>IssuerCertificateParser::inspect('invalid','secret','11222333000181'),'issuer_certificate_parse_failed','invalid file');
a1reject(fn()=>IssuerCertificateParser::inspect(str_repeat('x',2097153),'','11222333000181'),'issuer_certificate_invalid_upload','2 MiB size bound');
a1reject(fn()=>IssuerCertificateParser::inspect($a['pfx'],str_repeat('x',4097),'11222333000181'),'issuer_certificate_invalid_upload','password length bound');
a1reject(fn()=>IssuerCertificateParser::inspect($a['pfx'],$a['password'],'11222333000181',strtotime($m['valid_from'].' UTC')-1),'issuer_certificate_not_yet_valid','future validity');
a1reject(fn()=>IssuerCertificateParser::inspect($a['pfx'],$a['password'],'11222333000181',strtotime($m['valid_to'].' UTC')),'issuer_certificate_expired','expiry boundary');
$alpha=a1fixture('12ABC34501DE35');
a1check(IssuerCertificateParser::inspect($alpha['pfx'],$alpha['password'],'12.ABC.345/01DE-35')['document']==='12ABC34501DE35','alphanumeric CNPJ preserves canonical letters');
a1reject(fn()=>IssuerCertificateParser::inspect($a['pfx'],$a['password'],'A11222333000181'),'issuer_certificate_document_mismatch','invalid company document cannot be silently stripped into a matching CNPJ');
$badDocument=a1fixture('123');
a1reject(fn()=>IssuerCertificateParser::inspect($badDocument['pfx'],$badDocument['password'],'11222333000181'),'issuer_certificate_document_invalid','malformed otherName');
$duplicate=a1fixture('11222333000181,otherName:2.16.76.1.3.3;UTF8:11222333000181');
a1reject(fn()=>IssuerCertificateParser::inspect($duplicate['pfx'],$duplicate['password'],'11222333000181'),'issuer_certificate_document_invalid','duplicate CNPJ otherName is ambiguous');
$noKey=a1pkcs12(null,$a['certificate']);
a1reject(fn()=>IssuerCertificateParser::inspect($noKey,'','11222333000181'),'issuer_certificate_parse_failed','PKCS12 without private key');
$mismatch=a1pkcs12($a['private'],$b['certificate']);
a1reject(fn()=>IssuerCertificateParser::inspect($mismatch,'','11222333000181'),'issuer_certificate_parse_failed','PKCS12 mismatched private key');
$goodBare=a1pkcs12($a['private'],$a['certificate']);
a1check(IssuerCertificateParser::inspect($goodBare,'','11222333000181')['document_status']==='matched','synthetic PKCS12 fixture builder has usable private material');
$vault=new IssuerCertificateVault(a1encryption()); $sealed=$vault->seal(10,1,$m,$a['pfx'],$a['password']);
$vault->assertBound(10,1,$m,$sealed);
a1reject(fn()=>$vault->assertBound(20,1,$m,$sealed),'issuer_certificate_envelope_invalid','envelope cannot move across companies');
a1reject(fn()=>$vault->assertBound(10,2,$m,$sealed),'issuer_certificate_envelope_invalid','envelope cannot replay another revision');
$swapped=['pfx_cipher'=>$sealed['password_cipher'],'password_cipher'=>$sealed['pfx_cipher']];
a1reject(fn()=>$vault->assertBound(10,1,$m,$swapped),'issuer_certificate_envelope_invalid','purpose swap rejected');
$changed=$m; $changed['subject']='tampered';
a1reject(fn()=>$vault->assertBound(10,1,$changed,$sealed),'issuer_certificate_envelope_invalid','metadata tamper rejected');
$tampered=$sealed; $tampered['pfx_cipher'][150]=$tampered['pfx_cipher'][150]==='A'?'B':'A';
a1reject(fn()=>$vault->assertBound(10,1,$m,$tampered),'issuer_certificate_envelope_invalid','authenticated cipher tamper rejected');
a1check(!str_contains(json_encode($GLOBALS['a1_logs']),$a['password']),'logs contain no input secret');
echo "Certificate parser/vault tests complete. Synthetic certificates only.\n";
